style.css:
/* General Styles */
body {
    background-color: #1e1e1e;
    color: #f5f5f5;
    font-family: 'Arial', sans-serif;
    margin: 0;
    padding: 0;
}

/* Header */
header {
    background-color: #333;
    padding: 20px;
    text-align: center;
    border-bottom: 2px solid #444;
}

header h1 {
    margin: 0;
    font-size: 2em;
    color: #f5f5f5;
}

/* Navigation Bar */
nav {
    display: flex;
    justify-content: center;
    background-color: #444;
    padding: 10px;
}

nav a {
    color: #f5f5f5;
    text-decoration: none;
    margin: 0 15px;
    padding: 10px 20px;
    border-radius: 5px;
    transition: background-color 0.3s;
}

nav a:hover {
    background-color: #555;
}

/* Main Content */
main {
    padding: 20px;
}

main h2 {
    color: #f5f5f5;
    font-size: 1.5em;
    margin-bottom: 10px;
}

main p {
    line-height: 1.6;
}

/* Buttons */
button {
    background-color: #007bff;
    color: #fff;
    border: none;
    padding: 10px 20px;
    border-radius: 5px;
    cursor: pointer;
    transition: background-color 0.3s;
}

button:hover {
    background-color: #0056b3;
}

/* Footer */
footer {
    background-color: #333;
    color: #f5f5f5;
    text-align: center;
    padding: 10px;
    position: fixed;
    width: 100%;
    bottom: 0;
}
